Lemma at_mod4 : forall (a : word) d, (0 <= bv_unsigned a + d < 2^64)%Z ->
  ((bv_unsigned (at_ a d)) mod 4 = (bv_unsigned a + d) mod 4)%Z.
Proof. intros a d H. rewrite at_u by lia. reflexivity. Qed.
